cd src; for u in "https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2023AV000915" "https://agupubs.onlinelibrary.wiley.com/doi/pdfdirect/10.1029/2023AV000915" "https://api.crossref.org/works/10.1029/2023AV000915"; do curl -s -o /tmp/x -w "%{http_code} %{size_download}\n" -L --max-time 30 "$u"; done; python -c "
import json;d=json.load(open('/tmp/x'))['message']; print([l for l in d.get('link',[])]); print(d.get('license')); print([r.get('DOI') or r.get('unstructured','')[:150] for r in d.get('reference',[]) if 'zenodo' in json.dumps(r).lower() or 'figshare' in json.dumps(r).lower() or 'pangaea' in json.dumps(r).lower() or 'dryad' in json.dumps(r).lower()])"